import { useEffect, useState } from "react";
import type { ReactNode } from "react";
import { Activity, Bell, CalendarDays, ChevronRight, CircleDollarSign, ClipboardList, FileImage, LayoutDashboard, LogOut, Menu, Megaphone, PackageOpen, Radio, RefreshCw, Send, ShieldCheck, Users, X } from "lucide-react";
import type { HealthPayload } from "@tg-ad-manager/contracts";
import { ApiError, authenticate, bindChannel, cancelPublishTask, createCustomer, createOrder, createPackage, createPayment, createSchedule, getChannels, getCustomers, getHealth, getMedia, getOperationsSummary, getExpirationFailures, configureTelegramAlerts, downloadPaymentProof, getOrders, getPackages, getPendingPayments, getPendingRefunds, uploadPaymentProof, getPublishTasks, getReconciliation, getOrderTimeline, getSchedules, logout, retryPublishTask, openMediaPreview, replaceMediaAsset, reviewMediaAsset, retryExpirationFailure, acknowledgeExpirationFailure, reviewPayment, reviewRefund, submitOrder, createRefund, transitionOrder, getWorkspaceMembers, updateWorkspaceMember, removeWorkspaceMember, getAuditLogs } from "./lib/api";
import type { AuthData, Channel, Customer, MediaAsset, OperationsSummary, ExpirationFailure, Package, Order, Payment, PublishTask, Schedule, Refund, ReconciliationRow, TimelineEvent, WorkspaceMember, AuditLog } from "./lib/api";

type Page = "overview" | "channels" | "customers" | "packages" | "orders" | "finance" | "settings" | "schedules" | "media" | "publishes" | "members" | "audit";
const nav: Array<{ id: Page; label: string; icon: typeof LayoutDashboard }> = [
  { id: "overview", label: "概览", icon: LayoutDashboard }, { id: "channels", label: "频道", icon: Radio }, { id: "customers", label: "客户", icon: Users }, { id: "packages", label: "广告套餐", icon: PackageOpen }, { id: "orders", label: "广告订单", icon: Megaphone }, { id: "finance", label: "财务审核", icon: CircleDollarSign }, { id: "schedules", label: "排期日历", icon: CalendarDays }, { id: "media", label: "素材中心", icon: FileImage }, { id: "publishes", label: "发布任务", icon: Send }, { id: "settings", label: "告警配置", icon: Bell }, { id: "members", label: "成员管理", icon: Users }, { id: "audit", label: "操作审计", icon: ClipboardList },
];

type DataState = { channels: Channel[]; customers: Customer[]; packages: Package[]; orders: Order[]; schedules: Schedule[]; tasks: PublishTask[]; media: MediaAsset[]; pendingPayments: Payment[] };
const emptyData: DataState = { channels: [], customers: [], packages: [], orders: [], schedules: [], tasks: [], media: [], pendingPayments: [] };
const money = (minor: number) => `¥${(Number(minor || 0) / 100).toLocaleString("zh-CN", { minimumFractionDigits: 2 })}`;
const statusText: Record<string, string> = { active: "正常", draft: "草稿", pending_payment: "待付款", paid: "已付款", pending_review: "待审核", approved: "已通过", scheduled: "已排期", publishing: "发布中", published: "已发布", completed: "已完成", cancelled: "已取消", failed: "失败", queued: "排队中", processing: "处理中", success: "成功" };

function App() {
  const [page, setPage] = useState<Page>("overview");
  const [mobileOpen, setMobileOpen] = useState(false);
  const [auth, setAuth] = useState<AuthData | null>(null);
  const [health, setHealth] = useState<HealthPayload | null>(null);
  const [data, setData] = useState<DataState>(emptyData);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [loadDiagnostics, setLoadDiagnostics] = useState<string[]>([]);
  const [refreshing, setRefreshing] = useState(false);

  const loadData = async () => {
    setRefreshing(true); setError("");
    const requestLabels = ["频道 /api/v1/channels", "客户 /api/v1/customers", "套餐 /api/v1/packages", "订单 /api/v1/orders", "排期 /api/v1/schedules", "发布任务 /api/v1/publish-tasks", "素材 /api/v1/media-assets"];
    const results = await Promise.allSettled([getChannels(), getCustomers(), getPackages(), getOrders(), getSchedules(), getPublishTasks(), getMedia()]);
    const next = { ...emptyData };
    const [channels, customers, packages, orders, schedules, tasks, media] = results;
    const diagnostics = results.flatMap((result, index) => result.status === "rejected" ? [`${requestLabels[index]}：${result.reason instanceof ApiError ? `[${result.reason.code}] ${result.reason.message}（HTTP ${result.reason.status}）` : result.reason instanceof Error ? result.reason.message : String(result.reason)}`] : []);
    setLoadDiagnostics(diagnostics);
    if (channels.status === "fulfilled") next.channels = channels.value.channels;
    if (customers.status === "fulfilled") next.customers = customers.value.customers;
    if (packages.status === "fulfilled") next.packages = packages.value.packages;
    if (orders.status === "fulfilled") next.orders = orders.value.orders;
    if (schedules.status === "fulfilled") next.schedules = schedules.value.schedules;
    if (tasks.status === "fulfilled") next.tasks = tasks.value.tasks;
    if (media.status === "fulfilled") next.media = media.value.assets;
    if (auth && ["owner", "admin", "finance"].includes(auth.role)) { try { next.pendingPayments = (await getPendingPayments()).payments; } catch { next.pendingPayments = []; } }
    const failed = results.find((r) => r.status === "rejected") as PromiseRejectedResult | undefined;
    if (failed && !(failed.reason instanceof ApiError && failed.reason.code === "MEDIA_NOT_CONFIGURED")) setError(failed.reason instanceof Error ? failed.reason.message : "部分业务数据加载失败");
    setData(next); setRefreshing(false);
  };

  useEffect(() => { const controller = new AbortController(); getHealth(controller.signal).then((r) => r.ok && setHealth(r.data)).catch(() => undefined); authenticate().then(setAuth).catch((e) => setError(e instanceof ApiError ? `[${e.code}] ${e.message}` : e instanceof Error ? e.message : "Telegram 登录失败")).finally(() => setLoading(false)); return () => controller.abort(); }, []);
  useEffect(() => { if (auth) void loadData(); }, [auth]);

  if (loading) return <div className="center-state"><div className="loader" /><strong>正在连接 TG Ad Manager</strong><span>验证 Telegram 身份并加载工作空间…</span></div>;
  if (!auth) return <div className="center-state auth-state"><div className="brand-mark">TG</div><h1>TG Ad Manager</h1><p>{error || "请从 Telegram Bot 的“进入广告管理”按钮打开此 Mini App。"}</p><button className="primary-button" onClick={() => window.location.reload()}>重新连接</button></div>;

  const current = nav.find((item) => item.id === page) ?? nav[0];
  const choose = (id: Page) => { setPage(id); setMobileOpen(false); window.history.replaceState({}, "", id === "overview" ? "/" : `/${id}`); };
  return <div className="app-shell">
    <aside className={`sidebar ${mobileOpen ? "sidebar-open" : ""}`}><div className="brand-block"><div className="brand-mark">TG</div><div><div className="brand-name">TG Ad Manager</div><div className="brand-caption">商业广告运营平台</div></div><button className="icon-button mobile-close" onClick={() => setMobileOpen(false)}><X size={18} /></button></div>
      <div className="workspace-switcher"><div className="workspace-avatar">{auth.workspace.name.slice(0, 1)}</div><div className="workspace-copy"><strong>{auth.workspace.name}</strong><span>{auth.role === "owner" ? "工作空间所有者" : auth.role}</span></div></div>
      <nav className="main-nav">{nav.filter((item) => !["finance", "settings", "members", "audit"].includes(item.id) || (item.id === "finance" ? ["owner", "admin", "finance"].includes(auth.role) : ["owner", "admin"].includes(auth.role))).map(({ id, label, icon: Icon }) => <button key={id} className={`nav-item ${page === id ? "active" : ""}`} onClick={() => choose(id)}><Icon size={17} /><span>{label}</span>{page === id && <span className="active-pip" />}</button>)}</nav>
      <div className="sidebar-footer"><div className="operator-card"><div className="operator-avatar">{auth.user.displayName.slice(0, 1)}</div><div><strong>{auth.user.displayName}</strong><span>已认证 · {auth.role}</span></div></div><button className="nav-item muted" onClick={() => { void logout().finally(() => window.location.reload()); }}><LogOut size={17} /><span>退出登录</span></button></div>
    </aside>
    {mobileOpen && <button className="mobile-backdrop" onClick={() => setMobileOpen(false)} aria-label="关闭导航" />}
      <main className="main-content"><header className="topbar"><button className="icon-button mobile-menu" onClick={() => setMobileOpen(true)}><Menu size={20} /></button><div className="breadcrumb"><span>运营工作台</span><ChevronRight size={15} /><strong>{current.label}</strong></div><div className="topbar-actions"><div className="connection-pill"><span className={`status-dot ${health?.ok ? "online" : ""}`} />{health?.ok ? "生产 API 已连接" : "生产 API 状态未知"}</div><div className="profile-chip">{auth.user.displayName.slice(0, 1)}</div></div></header>
      <div className="content-wrap"><section className="page-heading"><div><div className="eyebrow">{auth.workspace.name} · 运营工作台</div><h1>{current.label}</h1><p>{pageSubtitle(page)}</p></div><button className="secondary-button toolbar-action-button" onClick={() => void loadData()} disabled={refreshing}><RefreshCw size={15} className={refreshing ? "spin" : ""} />刷新数据</button></section>{error && <div className="error-banner">{error}</div>}{loadDiagnostics.length > 0 && <div className="error-banner"><strong>接口诊断：</strong>{loadDiagnostics.map((item) => <div key={item}>{item}</div>)}</div>}{page === "overview" ? <Overview data={data} onNavigate={choose} /> : <PageContent page={page} data={data} auth={auth} onRefresh={loadData} />}</div>
    </main>
  </div>;
}

function pageSubtitle(page: Page) { return ({ overview: "查看真实业务指标、待办事项和系统运行状态", channels: "绑定频道并检查发布权限", customers: "管理广告主、联系人和合作记录", packages: "配置可售广告位和发布规则", orders: "跟踪订单状态、金额和履约进度", schedules: "管理发布排期和任务状态", media: "查看 Telegram Webhook 收集的真实素材", finance: "审核付款并推进订单履约", settings: "配置 Telegram 运维告警接收目标", publishes: "监控发布队列、重试和失败任务", members: "管理成员角色、状态和最近登录", audit: "查询关键业务操作及前后状态" } as Record<Page, string>)[page]; }
function Overview({ data, onNavigate }: { data: DataState; onNavigate: (page: Page) => void }) { const revenue = data.orders.reduce((sum, order) => sum + Number(order.receivable_minor || 0), 0); const pending = data.orders.filter((o) => ["draft", "pending_payment", "pending_review", "approved", "scheduled"].includes(o.status)).length; return <>
  <div className="status-banner"><div className="status-icon"><ShieldCheck size={19} /></div><div className="status-message"><strong>生产工作空间已连接</strong><span>数据来自当前 Telegram 租户，所有列表均经过后端权限和租户边界校验。</span></div><span className="live-chip">LIVE</span></div>
  <section className="metric-grid"><Metric label="活跃频道" value={String(data.channels.filter((c) => c.status === "active").length)} hint={`${data.channels.length} 个已绑定`} icon={Radio} onClick={() => onNavigate("channels")} /><Metric label="客户总数" value={String(data.customers.length)} hint="真实 CRM 数据" icon={Users} onClick={() => onNavigate("customers")} /><Metric label="待处理订单" value={String(pending)} hint={`${data.orders.length} 笔订单`} icon={Megaphone} onClick={() => onNavigate("orders")} /><Metric label="订单总额" value={money(revenue)} hint="当前工作空间累计" icon={CircleDollarSign} onClick={() => onNavigate("orders")} /></section>
  <section className="dashboard-grid"><article className="panel"><PanelTitle title="订单履约" kicker="REAL-TIME" /><div className="progress-list"><Progress label="已发布" value={data.orders.filter((o) => o.status === "published").length} total={Math.max(data.orders.length, 1)} tone="green" /><Progress label="待付款 / 审核" value={data.orders.filter((o) => ["pending_payment", "pending_review"].includes(o.status)).length} total={Math.max(data.orders.length, 1)} tone="orange" /><Progress label="排期中" value={data.orders.filter((o) => ["approved", "scheduled", "publishing"].includes(o.status)).length} total={Math.max(data.orders.length, 1)} tone="blue" /></div><button className="link-button" onClick={() => onNavigate("orders")}>查看全部订单 <ChevronRight size={15} /></button></article><article className="panel"><PanelTitle title="系统状态" kicker="PRODUCTION" /><div className="runtime-list"><Runtime label="API 服务" value="正常" good /><Runtime label="Telegram Bot" value="已配置" good /><Runtime label="数据库" value={data.channels ? "已连接" : "检查中"} good /><Runtime label="自动发布队列" value={`${data.tasks.length} 个任务`} good /></div></article></section>
  <section className="panel table-panel"><PanelTitle title="最近订单" kicker="WORKSPACE ACTIVITY" action={<button className="secondary-button small" onClick={() => onNavigate("orders")}>管理订单</button>} />{data.orders.length ? <OrderTable orders={data.orders.slice(0, 5)} /> : <Empty title="还没有订单" text="先绑定频道、创建客户和广告套餐，即可创建第一笔真实订单。" action="去绑定频道" onClick={() => onNavigate("channels")} />}</section>
</>; }
function Metric({ label, value, hint, icon: Icon, onClick }: { label: string; value: string; hint: string; icon: typeof Radio; onClick: () => void }) { return <button className="metric-card" onClick={onClick}><div className="metric-icon"><Icon size={18} /></div><div className="metric-label">{label}</div><div className="metric-value">{value}</div><div className="metric-hint">{hint}</div></button>; }
function PanelTitle({ title, kicker, action }: { title: string; kicker: string; action?: ReactNode }) { return <div className="panel-heading"><div><div className="panel-kicker">{kicker}</div><h2>{title}</h2></div>{action}</div>; }
function Progress({ label, value, total, tone }: { label: string; value: number; total: number; tone: string }) { const percent = Math.min(100, Math.round(value / total * 100)); return <div className="progress-row"><div><span>{label}</span><strong>{value}</strong></div><div className="progress-track"><span className={`progress-fill ${tone}`} style={{ width: `${percent}%` }} /></div></div>; }
function Runtime({ label, value, good }: { label: string; value: string; good?: boolean }) { return <div className="runtime-row"><span>{label}</span><span className={`state-chip ${good ? "good" : ""}`}><span className="mini-dot" />{value}</span></div>; }

function PageContent({ page, data, auth, onRefresh }: { page: Page; data: DataState; auth: AuthData; onRefresh: () => Promise<void> }) { if (page === "channels") return <Channels channels={data.channels} onRefresh={onRefresh} />; if (page === "customers") return <Customers customers={data.customers} onRefresh={onRefresh} />; if (page === "packages") return <Packages packages={data.packages} onRefresh={onRefresh} />; if (page === "orders") return <Orders data={data} auth={auth} onRefresh={onRefresh} />; if (page === "finance") return <Finance payments={data.pendingPayments} orders={data.orders} auth={auth} onRefresh={onRefresh} />; if (page === "settings") return <AlertSettings />; if (page === "schedules") return <Schedules schedules={data.schedules} data={data} onRefresh={onRefresh} />; if (page === "media") return <MediaCenter assets={data.media} onRefresh={onRefresh} />; if (page === "members") return <Members />; if (page === "audit") return <Audit />; return <PublishOperations tasks={data.tasks} onRefresh={onRefresh} />; }

function Members() { const [members, setMembers] = useState<WorkspaceMember[]>([]); const [message, setMessage] = useState(""); const [busy, setBusy] = useState<string | null>(null); const load = async () => { try { setMembers((await getWorkspaceMembers()).members); } catch (error) { setMessage(error instanceof Error ? error.message : "成员列表读取失败"); } }; useEffect(() => { void load(); }, []); const update = async (member: WorkspaceMember, input: { role?: string; status?: string }) => { setBusy(member.userId); setMessage(""); try { await updateWorkspaceMember(member.userId, input); await load(); } catch (error) { setMessage(error instanceof Error ? error.message : "成员更新失败"); } finally { setBusy(null); } }; const remove = async (member: WorkspaceMember) => { if (!window.confirm(`确认暂停成员“${member.displayName}”？`)) return; await update(member, { status: "suspended" }); }; return <section className="panel table-panel"><PanelTitle title="工作空间成员" kicker={`${members.length} MEMBERS`} /><p className="form-message">当前版本通过 Telegram 用户 ID 建立成员关系；owner 不能被降级或移除。暂停成员后将无法继续使用当前工作空间。</p>{message && <div className="error-banner">{message}</div>}{members.length ? <div className="record-list">{members.map((member) => <div className="record-row" key={member.userId}><div><strong>{member.displayName}</strong><span>{member.username ? `@${member.username.replace(/^@/, "")}` : `Telegram ID：${member.telegramUserId}`}</span><small>加入：{new Date(member.joinedAt).toLocaleString("zh-CN")} · 最近登录：{member.lastSeenAt ? new Date(member.lastSeenAt).toLocaleString("zh-CN") : "暂无记录"}</small></div><div className="button-row"><select value={member.role} disabled={busy !== null || member.role === "owner"} onChange={(e) => void update(member, { role: e.target.value })}><option value="owner">owner</option><option value="admin">admin</option><option value="manager">manager</option><option value="editor">editor</option><option value="finance">finance</option><option value="viewer">viewer</option></select><button className="secondary-button small" disabled={busy !== null || member.role === "owner"} onClick={() => void update(member, { status: member.status === "active" ? "suspended" : "active" })}>{member.status === "active" ? "暂停" : "恢复"}</button>{member.role !== "owner" && <button className="secondary-button small" disabled={busy !== null} onClick={() => void remove(member)}>移除</button>}</div></div>)}</div> : <Empty title="暂无成员" text="当前工作空间还没有可管理的成员。" />}</section>; }

function Audit() { const [logs, setLogs] = useState<AuditLog[]>([]); const [message, setMessage] = useState(""); useEffect(() => { getAuditLogs().then((result) => setLogs(result.logs)).catch((error) => setMessage(error instanceof Error ? error.message : "审计日志读取失败")); }, []); return <section className="panel table-panel"><PanelTitle title="操作审计" kicker={`${logs.length} LOGS`} /><p className="form-message">审计记录按当前租户隔离，展示操作者、动作、对象、结果及操作前后摘要；敏感凭证不会写入日志。</p>{message && <div className="error-banner">{message}</div>}{logs.length ? <div className="record-list">{logs.map((log) => <div className="record-row" key={log.id}><div><strong>{log.actorDisplayName || log.actorUserId || "系统"} · {log.action}</strong><span>{log.entityType} / {log.entityId} · {log.result}</span><small>{new Date(log.createdAt).toLocaleString("zh-CN")} · {log.source}</small>{(log.beforeSummary || log.afterSummary) && <small>前：{log.beforeSummary || "—"} · 后：{log.afterSummary || "—"}</small>}</div></div>)}</div> : <Empty title="暂无审计记录" text="后续成员和关键业务操作会在这里按时间倒序显示。" />}</section>; }

function MediaCenter({ assets, onRefresh }: { assets: MediaAsset[]; onRefresh: () => Promise<void> }) { const [filter, setFilter] = useState("all"); const [note, setNote] = useState<Record<string, string>>({}); const [replacement, setReplacement] = useState<Record<string, string>>({}); const [busy, setBusy] = useState<string | null>(null); const [message, setMessage] = useState(""); const visible = assets.filter((asset) => filter === "all" || asset.media_type === filter || (filter === "group" && Boolean(asset.media_group_id))); const act = async (id: string, action: "approved" | "rejected" | "preview" | "replace") => { setBusy(`${action}:${id}`); setMessage(""); try { if (action === "preview") await openMediaPreview(id); else if (action === "replace") { const source = replacement[id]; if (!source) throw new Error("请先选择替换素材"); await replaceMediaAsset(id, source); setMessage("素材已替换，并重新进入待审核状态"); await onRefresh(); } else { await reviewMediaAsset(id, action, note[id]); setMessage(action === "approved" ? "素材已审核通过" : "素材已驳回"); await onRefresh(); } } catch (error) { setMessage(error instanceof Error ? error.message : "素材操作失败"); } finally { setBusy(null); } }; return <section className="panel table-panel"><PanelTitle title="素材中心" kicker={`${assets.length} MEDIA ASSETS`} action={<div className="media-filter"><select value={filter} onChange={(e) => setFilter(e.target.value)}><option value="all">全部类型</option><option value="photo">图片</option><option value="video">视频</option><option value="document">文件</option><option value="group">媒体组</option></select></div>} />{message && <div className="form-message">{message}</div>}{visible.length ? <div className="record-list">{visible.map((asset) => { const status = asset.review_status || "pending"; const alternatives = assets.filter((candidate) => candidate.id !== asset.id && candidate.media_type === asset.media_type); return <div className="record-row media-record" key={asset.id}><div className="media-record-main"><strong>{asset.file_name || `${asset.media_type} · ${asset.id.slice(0, 8)}`}</strong><span>{asset.media_type} · {asset.file_size ? `${Math.round(asset.file_size / 1024)} KB` : "大小未知"}{asset.media_group_id ? " · 媒体组" : ""}</span><span>审核状态：<b className={`status-inline ${status}`}>{status === "approved" ? "已通过" : status === "rejected" ? "已驳回" : "待审核"}</b>{asset.review_note ? ` · ${asset.review_note}` : ""}</span></div><div className="media-actions"><button className="secondary-button small" disabled={busy !== null} onClick={() => void act(asset.id, "preview")}>{busy === `preview:${asset.id}` ? "打开中…" : "预览"}</button>{status !== "approved" && <button className="primary-button small" disabled={busy !== null} onClick={() => void act(asset.id, "approved")}>{busy === `approved:${asset.id}` ? "审核中…" : "通过"}</button>}<button className="secondary-button small" disabled={busy !== null} onClick={() => void act(asset.id, "rejected")}>驳回</button>{alternatives.length > 0 && <><select aria-label="选择替换素材" value={replacement[asset.id] || ""} onChange={(e) => setReplacement({ ...replacement, [asset.id]: e.target.value })}><option value="">选择替换素材</option>{alternatives.map((candidate) => <option key={candidate.id} value={candidate.id}>{candidate.file_name || candidate.id.slice(0, 8)}</option>)}</select><button className="secondary-button small" disabled={busy !== null || !replacement[asset.id]} onClick={() => void act(asset.id, "replace")}>替换</button></>}</div>{status !== "approved" && <input className="review-note" value={note[asset.id] || ""} onChange={(e) => setNote({ ...note, [asset.id]: e.target.value })} placeholder="驳回原因（驳回必填）" />}</div>; })}</div> : <Empty title="暂无素材" text="Webhook 尚未收集到图片、视频、文件或媒体组；向 Bot 或已绑定频道发送媒体后会出现在这里。" />}</section>; }

function PublishOperations({ tasks, onRefresh }: { tasks: PublishTask[]; onRefresh: () => Promise<void> }) { const [summary, setSummary] = useState<OperationsSummary | null>(null); const [failures, setFailures] = useState<ExpirationFailure[]>([]); const [busy, setBusy] = useState<string | null>(null); const [message, setMessage] = useState(""); const [notes, setNotes] = useState<Record<string, string>>({}); const load = async () => { try { const [nextSummary, nextFailures] = await Promise.all([getOperationsSummary(), getExpirationFailures()]); setSummary(nextSummary); setFailures(nextFailures.failures); } catch (error) { setMessage(error instanceof Error ? error.message : "运维状态读取失败"); } }; useEffect(() => { void load(); }, [tasks]); const act = async (taskId: string, action: "retry" | "cancel") => { setBusy(`${action}:${taskId}`); setMessage(""); try { if (action === "retry") await retryPublishTask(taskId); else await cancelPublishTask(taskId); await onRefresh(); await load(); } catch (error) { setMessage(error instanceof Error ? error.message : "操作失败"); } finally { setBusy(null); } }; const expirationAct = async (failure: ExpirationFailure, action: "retry" | "ack") => { setBusy(`${action}:${failure.id}`); setMessage(""); try { if (action === "retry") await retryExpirationFailure(failure.id); else await acknowledgeExpirationFailure(failure.id, notes[failure.id]); await load(); } catch (error) { setMessage(error instanceof Error ? error.message : "到期删除失败操作失败"); } finally { setBusy(null); } }; return <><section className="panel table-panel"><PanelTitle title="发布任务运维" kicker="PRODUCTION QUEUE" /><div className="runtime-list"><Runtime label="异常任务" value={`${(summary?.taskCounts.failed ?? 0) + (summary?.taskCounts.dead_letter ?? 0)} 个`} good={!((summary?.taskCounts.failed ?? 0) + (summary?.taskCounts.dead_letter ?? 0))} /><Runtime label="不确定任务" value={`${summary?.taskCounts.uncertain ?? 0} 个`} good={!summary?.taskCounts.uncertain} /><Runtime label="卡住任务" value={`${summary?.staleProcessing ?? 0} 个`} good={!summary?.staleProcessing} /><Runtime label="未关闭告警" value={`${summary?.openAlerts ?? 0} 个`} good={!summary?.openAlerts} /></div>{summary?.latestCron && <p className="form-message">最近 Cron：{summary.latestCron.status === "ok" ? "正常" : summary.latestCron.status === "degraded" ? "有异常任务" : "执行失败"} · {new Date(summary.latestCron.checkedAt).toLocaleString("zh-CN")}</p>}{message && <div className="error-banner">{message}</div>}</section><section className="panel table-panel"><PanelTitle title="到期删除失败补偿" kicker={`${failures.length} EXPIRATION FAILURES`} />{failures.length ? <div className="record-list">{failures.map((failure) => <div className="record-row expiration-row" key={failure.id}><div><strong>订单 {failure.orderId}</strong><span>{failure.lastError || "到期删除失败"}</span><span>状态：{statusText[failure.status] || failure.status} · 尝试 {failure.attempts} 次 · 下次重试：{failure.nextAttemptAt ? new Date(failure.nextAttemptAt).toLocaleString("zh-CN") : "未安排"}</span><small>首次失败：{failure.firstFailedAt ? new Date(failure.firstFailedAt).toLocaleString("zh-CN") : "—"}</small></div><div className="button-row"><input className="review-note" value={notes[failure.id] ?? ""} onChange={(e) => setNotes({ ...notes, [failure.id]: e.target.value })} placeholder="人工确认备注" /><button className="secondary-button" disabled={busy !== null || !["pending", "retrying"].includes(failure.status)} onClick={() => void expirationAct(failure, "retry")}>{busy === `retry:${failure.id}` ? "重试中…" : "立即重试"}</button><button className="secondary-button" disabled={busy !== null || !["pending", "retrying"].includes(failure.status)} onClick={() => void expirationAct(failure, "ack")}>{busy === `ack:${failure.id}` ? "确认中…" : "人工确认"}</button></div></div>)}</div> : <Empty title="暂无到期删除失败" text="Cron 到期删除失败时，记录会自动出现在这里。" />}</section><section className="panel table-panel"><PanelTitle title="任务列表" kicker={`${tasks.length} TASKS`} />{tasks.length ? <div className="record-list">{tasks.map((task) => { const actionable = ["failed", "uncertain", "dead_letter", "cancelled", "queued"].includes(task.status); return <div className="record-row" key={task.id}><div><strong>{task.order_id || task.id}</strong><span>{statusText[task.status] || task.status} · 尝试 {task.attempt_count ?? task.attempts ?? 0}</span></div><div className="button-row">{actionable && ["failed", "uncertain", "dead_letter", "cancelled"].includes(task.status) && <button className="secondary-button" disabled={busy !== null} onClick={() => void act(task.id, "retry")}>{busy === `retry:${task.id}` ? "处理中…" : "重试"}</button>}{actionable && <button className="secondary-button" disabled={busy !== null} onClick={() => void act(task.id, "cancel")}>{busy === `cancel:${task.id}` ? "处理中…" : "取消"}</button>}</div></div>; })}</div> : <Empty title="暂无发布任务" text="订单排期后，发布任务会出现在这里。" />}</section></>; }
function Channels({ channels, onRefresh }: { channels: Channel[]; onRefresh: () => Promise<void> }) { const [chatId, setChatId] = useState(""); const [busy, setBusy] = useState(false); const [message, setMessage] = useState(""); const submit = async () => { if (!chatId.trim()) return; setBusy(true); setMessage(""); try { await bindChannel(chatId.trim()); setChatId(""); setMessage("频道绑定成功，权限检查已完成"); await onRefresh(); } catch (e) { setMessage(e instanceof Error ? e.message : "频道绑定失败"); } finally { setBusy(false); } }; return <><section className="action-panel panel"><div><div className="panel-kicker">CHANNEL ACCESS</div><h2>绑定 Telegram 频道</h2><p>先将 @TGAdOpsBot 添加为频道管理员，并授予发布、编辑和删除消息权限，再输入频道用户名或 Chat ID。</p></div><div className="inline-form"><input value={chatId} onChange={(e) => setChatId(e.target.value)} placeholder="@your_channel 或 -100..." /><button className="primary-button" onClick={submit} disabled={busy}>{busy ? "检查中…" : "绑定并检查"}</button></div>{message && <div className="form-message">{message}</div>}</section><section className="panel table-panel"><PanelTitle title="已绑定频道" kicker={`${channels.length} CHANNELS`} />{channels.length ? <ChannelTable channels={channels} /> : <Empty title="暂无已绑定频道" text="绑定第一个频道后，广告套餐和订单才能选择真实投放渠道。" />}</section></>; }
function Customers({ customers, onRefresh }: { customers: Customer[]; onRefresh: () => Promise<void> }) { const [name, setName] = useState(""); const [contact, setContact] = useState(""); const [telegramUserId, setTelegramUserId] = useState(""); const [telegramUsername, setTelegramUsername] = useState(""); const [busy, setBusy] = useState(false); const submit = async () => { if (!name.trim()) return; setBusy(true); try { await createCustomer({ name: name.trim(), contact: contact.trim(), telegramUserId: telegramUserId.trim() || undefined, telegramUsername: telegramUsername.trim() || undefined, source: "manual" }); setName(""); setContact(""); setTelegramUserId(""); setTelegramUsername(""); await onRefresh(); } finally { setBusy(false); } }; return <><section className="action-panel panel"><div><div className="panel-kicker">CRM</div><h2>新增客户</h2><p>填写 Telegram 用户 ID 或用户名后，系统才能向客户发送订单状态通知；两者都没有也可以先创建客户。</p></div><div className="form-grid"><input value={name} onChange={(e) => setName(e.target.value)} placeholder="客户名称 *" /><input value={contact} onChange={(e) => setContact(e.target.value)} placeholder="联系方式" /><input value={telegramUserId} onChange={(e) => setTelegramUserId(e.target.value)} placeholder="Telegram 用户 ID（推荐）" /><input value={telegramUsername} onChange={(e) => setTelegramUsername(e.target.value)} placeholder="Telegram 用户名，如 @alice" /><button className="primary-button" onClick={submit} disabled={busy}>{busy ? "保存中…" : "保存客户"}</button></div></section><section className="panel table-panel"><PanelTitle title="客户列表" kicker={`${customers.length} CUSTOMERS`} />{customers.length ? <CustomerTable customers={customers} /> : <Empty title="暂无客户" text="先新增一个客户，再创建订单。" />}</section></>; }
function Packages({ packages, onRefresh }: { packages: Package[]; onRefresh: () => Promise<void> }) { const [name, setName] = useState(""); const [adType, setAdType] = useState("text"); const [price, setPrice] = useState(""); const [publishCount, setPublishCount] = useState("1"); const [message, setMessage] = useState(""); const [busy, setBusy] = useState(false); const submit = async () => { setBusy(true); setMessage(""); try { await createPackage({ name: name.trim(), adType, priceMinor: Math.round(Number(price) * 100), publishCount: Number(publishCount), isPublic: true }); setName(""); setPrice(""); setPublishCount("1"); setMessage("套餐已创建"); await onRefresh(); } catch (e) { setMessage(e instanceof Error ? e.message : "创建套餐失败"); } finally { setBusy(false); } }; return <><section className="action-panel panel"><div><div className="panel-kicker">PACKAGE CATALOG</div><h2>创建广告套餐</h2><p>价格以元填写，系统会按分保存；创建后可直接用于新订单。</p></div><div className="form-grid"><input value={name} onChange={(e) => setName(e.target.value)} placeholder="套餐名称 *" /><input value={adType} onChange={(e) => setAdType(e.target.value)} placeholder="广告类型，如 text / photo" /><input type="number" min="0" step="0.01" value={price} onChange={(e) => setPrice(e.target.value)} placeholder="价格（元）*" /><input type="number" min="1" step="1" value={publishCount} onChange={(e) => setPublishCount(e.target.value)} placeholder="发布次数" /><button className="primary-button" onClick={submit} disabled={busy || !name.trim() || !price}>{busy ? "创建中…" : "创建套餐"}</button></div>{message && <div className="form-message">{message}</div>}</section><section className="panel table-panel"><PanelTitle title="广告套餐" kicker={`${packages.length} PACKAGES`} />{packages.length ? <div className="package-grid">{packages.map((p) => <article className="package-card" key={p.id}><div className="package-top"><span className="package-type">{p.ad_type}</span><span className="state-chip good">{p.is_enabled ? "在售" : "停用"}</span></div><h3>{p.name}</h3><p>{p.description || "未填写套餐说明"}</p><strong>{money(p.price_minor)}</strong><small>{p.publish_count} 次发布 · {p.is_public ? "公开" : "私有"}</small></article>)}</div> : <Empty title="暂无广告套餐" text="创建第一个可售套餐后即可创建订单。" />}</section></>; }
function Orders({ data, auth, onRefresh }: { data: DataState; auth: AuthData; onRefresh: () => Promise<void> }) {
  const [selectedAssetIds, setSelectedAssetIds] = useState<string[]>([]);
  const [customerId, setCustomerId] = useState("");
  const [channelId, setChannelId] = useState("");
  const [packageId, setPackageId] = useState("");
  const [content, setContent] = useState("");
  const [submitOrderId, setSubmitOrderId] = useState("");
  const [paymentOrderId, setPaymentOrderId] = useState("");
  const [paymentAmount, setPaymentAmount] = useState("");
  const [paymentMethod, setPaymentMethod] = useState("bank_transfer");
  const [transactionRef, setTransactionRef] = useState("");
  const [proofAssetId, setProofAssetId] = useState("");
  const [proofFileName, setProofFileName] = useState("");
  const [proofUploadBusy, setProofUploadBusy] = useState(false);
  const [proofUploadMessage, setProofUploadMessage] = useState("");
  const [timelineOrderId, setTimelineOrderId] = useState("");
  const [timeline, setTimeline] = useState<TimelineEvent[]>([]);
  const [refundAmount, setRefundAmount] = useState("");
  const [refundReason, setRefundReason] = useState("");
  const [approvalOrderId, setApprovalOrderId] = useState("");
  const [message, setMessage] = useState("");
  const [busy, setBusy] = useState(false);
  const run = async (work: () => Promise<unknown>, success: string) => { setBusy(true); setMessage(""); try { await work(); setMessage(success); await onRefresh(); } catch (e) { setMessage(e instanceof Error ? e.message : "操作失败"); } finally { setBusy(false); } };
  const create = async () => run(async () => { const result = await createOrder({ customerId, channelId, packageId, content: { text: content, assetIds: selectedAssetIds, entities: [] } }); setMessage(`订单 ${result.orderNo} 已创建`); setCustomerId(""); setChannelId(""); setPackageId(""); setContent(""); setSelectedAssetIds([]); }, "订单已创建");
  const submitOrderForPayment = () => run(async () => { await submitOrder(submitOrderId); setSubmitOrderId(""); }, "订单已提交，现可录入付款");
  const submitPayment = () => run(async () => { await createPayment(paymentOrderId, { amountMinor: Math.round(Number(paymentAmount) * 100), method: paymentMethod, transactionRef: transactionRef.trim() || undefined, proofAssetId: proofAssetId || undefined }); setPaymentOrderId(""); setPaymentAmount(""); setTransactionRef(""); setProofAssetId(""); setProofFileName(""); setProofUploadMessage(""); }, "付款已提交，等待 Finance 审核");
  const financeRole = ["owner", "admin", "finance"].includes(auth.role);
  return <>
    <section className="action-panel panel"><div><div className="panel-kicker">ORDER INTAKE</div><h2>创建广告订单</h2><p>选择真实客户、已验证频道和在售套餐，先创建文字广告订单。</p></div><div className="form-grid"><select value={customerId} onChange={(e) => setCustomerId(e.target.value)}><option value="">选择客户 *</option>{data.customers.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}</select><select value={channelId} onChange={(e) => setChannelId(e.target.value)}><option value="">选择频道 *</option>{data.channels.filter((c) => c.status === "active").map((c) => <option key={c.id} value={c.id}>{c.title || c.username || c.telegram_chat_id}</option>)}</select><select value={packageId} onChange={(e) => setPackageId(e.target.value)}><option value="">选择套餐 *</option>{data.packages.filter((p) => p.is_enabled).map((p) => <option key={p.id} value={p.id}>{p.name} · {money(p.price_minor)}</option>)}</select><textarea value={content} onChange={(e) => setContent(e.target.value)} placeholder="广告正文（最多 4096 字）" rows={3} /><div className="order-media-picker"><div className="picker-heading"><strong>选择已审核素材 / 媒体组</strong><span>{selectedAssetIds.length ? `已选 ${selectedAssetIds.length} 个` : "可不选，创建纯文字广告"}</span></div><div className="media-picker-list">{data.media.filter((asset) => asset.review_status === "approved").map((asset) => <label className={`media-picker-item ${selectedAssetIds.includes(asset.id) ? "selected" : ""}`} key={asset.id}><input type="checkbox" checked={selectedAssetIds.includes(asset.id)} onChange={(e) => setSelectedAssetIds(e.target.checked ? [...selectedAssetIds, asset.id] : selectedAssetIds.filter((id) => id !== asset.id))} /><span><strong>{asset.file_name || `${asset.media_type} · ${asset.id.slice(0, 8)}`}</strong><small>{asset.media_type}{asset.media_group_id ? ` · 媒体组 ${asset.media_group_id}` : ""}{asset.file_size ? ` · ${Math.round(asset.file_size / 1024)} KB` : ""}</small></span></label>)}{!data.media.some((asset) => asset.review_status === "approved") && <small className="form-message">暂无已审核素材，请先到素材中心完成审核。</small>}</div>{selectedAssetIds.length > 0 && <div className="order-preview-card"><div className="panel-kicker">PUBLISH PREVIEW</div><strong>发布前组合预览</strong><p>{content.trim() || "（无正文）"}</p><div className="preview-asset-strip">{selectedAssetIds.map((id, index) => { const asset = data.media.find((item) => item.id === id); return asset ? <span key={id}>{index + 1}. {asset.file_name || asset.media_type}</span> : null; })}</div><small>发布时将按当前顺序发送，共 {selectedAssetIds.length} 个素材。</small></div>}</div><button className="primary-button" onClick={() => void create()} disabled={busy || !customerId || !channelId || !packageId}>创建订单</button></div>{message && <div className="form-message">{message}</div>}</section>
    <section className="action-panel panel"><div><div className="panel-kicker">ORDER SUBMISSION</div><h2>提交订单</h2><p>订单创建后先提交审核，提交成功后才可以录入付款。</p></div><div className="inline-form"><select value={submitOrderId} onChange={(e) => setSubmitOrderId(e.target.value)}><option value="">选择草稿订单 *</option>{data.orders.filter((o) => o.status === "draft").map((o) => <option key={o.id} value={o.id}>{o.order_no} · {money(o.receivable_minor)}</option>)}</select><button className="primary-button" onClick={() => void submitOrderForPayment()} disabled={busy || !submitOrderId}>提交订单</button></div></section>
    <section className="action-panel panel"><div><div className="panel-kicker">PAYMENT SUBMISSION</div><h2>提交付款</h2><p>选择待付款订单，填写实际收款金额和交易信息。付款提交后由 Finance 审核。</p></div><div className="form-grid"><select value={paymentOrderId} onChange={(e) => { const id = e.target.value; setPaymentOrderId(id); const order = data.orders.find((item) => item.id === id); setPaymentAmount(order ? String(order.receivable_minor / 100) : ""); }}><option value="">选择待付款订单 *</option>{data.orders.filter((o) => o.status === "pending_payment").map((o) => <option key={o.id} value={o.id}>{o.order_no} · {money(o.receivable_minor)}</option>)}</select><input type="number" min="0.01" step="0.01" value={paymentAmount} onChange={(e) => setPaymentAmount(e.target.value)} placeholder="付款金额（元）*" /><select value={paymentMethod} onChange={(e) => setPaymentMethod(e.target.value)}><option value="bank_transfer">银行转账</option><option value="alipay">支付宝</option><option value="wechat">微信</option><option value="cash">现金</option><option value="crypto">数字货币</option><option value="other">其他</option></select><input value={transactionRef} onChange={(e) => setTransactionRef(e.target.value)} placeholder="交易单号（可选）" /><div className="proof-upload-control"><label className="file-button secondary-button">{proofUploadBusy ? "上传中…" : "上传付款凭证"}<input type="file" accept="image/jpeg,image/png,image/webp,application/pdf" disabled={proofUploadBusy} onChange={async (e) => { const file = e.target.files?.[0]; if (!file) return; setProofUploadBusy(true); setProofUploadMessage(""); try { const result = await uploadPaymentProof(file); setProofAssetId(result.proofAssetId); setProofFileName(result.fileName); setProofUploadMessage(`已上传：${result.fileName}`); } catch (error) { setProofUploadMessage(error instanceof Error ? error.message : "凭证上传失败"); } finally { setProofUploadBusy(false); e.target.value = ""; } }} /></label><select value={proofAssetId && !proofFileName ? proofAssetId : ""} onChange={(e) => { setProofAssetId(e.target.value); setProofFileName(""); }}><option value="">或选择已有凭证</option>{data.media.filter((asset) => ["photo", "document", "animation"].includes(String(asset.media_type))).map((asset) => <option key={String(asset.id)} value={String(asset.id)}>{String(asset.file_name ?? asset.id).slice(0, 40)}</option>)}</select>{proofUploadMessage && <span className="form-message">{proofUploadMessage}</span>}</div><button className="primary-button" onClick={() => void submitPayment()} disabled={busy || !paymentOrderId || !paymentAmount}>提交付款</button></div></section>
    <section className="panel table-panel"><PanelTitle title="广告订单" kicker={`${data.orders.length} ORDERS`} />{data.orders.length ? <><div className="inline-form order-tools"><select value={timelineOrderId} onChange={async (e) => { const id = e.target.value; setTimelineOrderId(id); if (id) { try { setTimeline((await getOrderTimeline(id)).events); } catch { setTimeline([]); } } else setTimeline([]); }}><option value="">查看订单完整时间线</option>{data.orders.map((o) => <option key={o.id} value={o.id}>{o.order_no}</option>)}</select></div><OrderTable orders={data.orders} />{timelineOrderId && <div className="timeline-list">{timeline.length ? timeline.map((event, index) => <div className="timeline-row" key={`${event.objectId ?? event.type}-${index}`}><span className="timeline-dot" /><div><strong>{event.type === "payment" ? "付款" : event.type === "refund" ? "退款" : event.type === "ledger" ? "财务记账" : event.type}</strong><span>{new Date(event.createdAt).toLocaleString("zh-CN")}{event.amountMinor != null ? ` · ${money(event.amountMinor)}` : ""}{event.status ? ` · ${statusText[event.status] || event.status}` : ""}{event.reason ? ` · ${event.reason}` : ""}</span></div></div>) : <p className="form-message">该订单暂无可展示的时间线事件。</p>}</div>}</> : <Empty title="暂无订单" text="完成客户、频道和套餐配置后，即可创建第一笔订单。" />}</section><section className="action-panel panel"><div><div className="panel-kicker">REFUND REQUEST</div><h2>申请退款</h2><p>仅能申请不超过已审核付款未退款余额的金额，提交后由 Finance 审核。</p></div><div className="form-grid"><select value={timelineOrderId} onChange={(e) => setTimelineOrderId(e.target.value)}><option value="">选择已付款订单 *</option>{data.orders.filter((o) => ["paid", "completed", "partially_refunded"].includes(o.status)).map((o) => <option key={o.id} value={o.id}>{o.order_no}</option>)}</select><input type="number" min="0.01" step="0.01" value={refundAmount} onChange={(e) => setRefundAmount(e.target.value)} placeholder="退款金额（元）*" /><input value={refundReason} onChange={(e) => setRefundReason(e.target.value)} placeholder="退款原因 *" /><button className="primary-button" disabled={busy || !timelineOrderId || !refundAmount || !refundReason.trim()} onClick={() => void run(async () => { await createRefund(timelineOrderId, { amountMinor: Math.round(Number(refundAmount) * 100), reason: refundReason.trim(), method: "bank_transfer" }); setRefundAmount(""); setRefundReason(""); }, "退款申请已提交，等待 Finance 审核")}>提交退款申请</button></div></section>
    {financeRole && <section className="action-panel panel"><div><div className="panel-kicker">ORDER APPROVAL</div><h2>审核已付款订单</h2><p>付款全额批准后，Finance 可以将订单推进为已通过，之后才能创建排期。</p></div><div className="inline-form"><select value={approvalOrderId} onChange={(e) => setApprovalOrderId(e.target.value)}><option value="">选择已付款订单 *</option>{data.orders.filter((o) => o.status === "paid").map((o) => <option key={o.id} value={o.id}>{o.order_no} · {money(o.receivable_minor)}</option>)}</select><button className="primary-button" onClick={() => void run(() => transitionOrder(approvalOrderId, "approved", "finance_approved"), "订单已审核通过")} disabled={busy || !approvalOrderId}>审核通过</button></div></section>}
  </>;
}

function AlertSettings() {
  const [chatId, setChatId] = useState(""); const [busy, setBusy] = useState(false); const [message, setMessage] = useState(""); const [error, setError] = useState("");
  const save = async () => { const value = chatId.trim(); if (!value) { setError("请输入 Telegram 群组、频道用户名或数字 Chat ID"); return; } setBusy(true); setMessage(""); setError(""); try { await configureTelegramAlerts(value); setMessage("Telegram 告警目标已保存。后续新告警会发送到该目标；系统不会在页面显示 Bot Token。"); } catch (e) { setError(e instanceof Error ? e.message : "告警配置失败，请确认当前账号是 owner/admin"); } finally { setBusy(false); } };
  return <><section className="action-panel panel"><div><div className="panel-kicker">TELEGRAM OPERATIONS ALERTS</div><h2>配置 Telegram 告警</h2><p>填写接收运维告警的群组或频道 Chat ID。私有群通常是 -100 开头的数字；公开频道可填写 @username。</p></div><div className="form-grid alert-settings-form"><input value={chatId} onChange={(e) => setChatId(e.target.value)} placeholder="例如 -1001234567890 或 @my_alerts" /><button className="primary-button" onClick={() => void save()} disabled={busy || !chatId.trim()}>{busy ? "保存中…" : "保存告警目标"}</button></div>{message && <div className="form-message">{message}</div>}{error && <div className="error-banner">{error}</div>}</section><section className="panel table-panel"><PanelTitle title="配置前检查" kicker="SAFE DELIVERY CHECKLIST" /><div className="runtime-list"><Runtime label="Bot 身份" value="@TGAdOpsBot" good /><Runtime label="Bot 权限" value="需允许发送消息" /><Runtime label="目标 Chat ID" value={chatId.trim() ? "已填写，待保存" : "未填写"} good={Boolean(chatId.trim())} /><Runtime label="Token 安全" value="不会暴露到前端" good /></div><p className="form-message">保存后系统会写入当前工作空间的 Telegram 通知渠道。请先把 Bot 加入目标群/频道并授予发送消息权限。</p></section></>;
}

function Finance({ payments, orders, auth, onRefresh }: { payments: Payment[]; orders: Order[]; auth: AuthData; onRefresh: () => Promise<void> }) {
  const [busy, setBusy] = useState(false); const [message, setMessage] = useState(""); const [refunds, setRefunds] = useState<Refund[]>([]); const [reconciliation, setReconciliation] = useState<ReconciliationRow[]>([]); const [notes, setNotes] = useState<Record<string, string>>({}); const [proofBusy, setProofBusy] = useState<string | null>(null);
  const loadFinance = async () => { try { const [r, c] = await Promise.all([getPendingRefunds(), getReconciliation()]); setRefunds(r.refunds); setReconciliation(c.orders); } catch (e) { setMessage(e instanceof Error ? e.message : "财务数据读取失败"); } };
  useEffect(() => { void loadFinance(); }, [payments.length, orders.length]);
  const review = async (paymentId: string, status: "approved" | "rejected") => { const note = notes[paymentId]?.trim(); if (status === "rejected" && !note) { setMessage("驳回付款必须填写原因"); return; } setBusy(true); setMessage(""); try { await reviewPayment(paymentId, { status, note: note || undefined }); setMessage(status === "approved" ? "付款已批准" : "付款已驳回"); await onRefresh(); await loadFinance(); } catch (e) { setMessage(e instanceof Error ? e.message : "付款审核失败"); } finally { setBusy(false); } };
  const reviewRefundAction = async (id: string, status: "approved" | "rejected") => { const note = notes[id]?.trim(); if (status === "rejected" && !note) { setMessage("驳回退款必须填写原因"); return; } setBusy(true); try { await reviewRefund(id, { status, note: note || undefined }); setMessage(status === "approved" ? "退款已批准并记账" : "退款已驳回"); await onRefresh(); await loadFinance(); } catch (e) { setMessage(e instanceof Error ? e.message : "退款审核失败"); } finally { setBusy(false); } }; const openProof = async (proofId: string) => { setProofBusy(proofId); setMessage(""); try { await downloadPaymentProof(proofId); } catch (e) { setMessage(e instanceof Error ? e.message : "凭证下载失败"); } finally { setProofBusy(null); } };
  if (!(auth.role === "owner" || auth.role === "admin" || auth.role === "finance")) return <Empty title="无财务权限" text="只有 owner、admin 或 finance 角色可以查看财务数据。" />;
  return <><section className="panel table-panel"><PanelTitle title="Finance 待审核付款" kicker={`${payments.length} PENDING`} />{message && <div className="form-message">{message}</div>}{payments.length ? <div className="data-table finance-table"><div className="table-head"><span>订单</span><span>金额</span><span>方式 / 交易号</span><span>凭证</span><span>审核</span></div>{payments.map((payment) => <div className="table-row" key={payment.id}><strong>{payment.order_id.slice(0, 8)}</strong><span>{money(payment.amount_minor)}</span><span>{payment.method}{payment.transaction_ref ? ` · ${payment.transaction_ref}` : ""}</span><span>{payment.proof_asset_id ? <button className="link-button" onClick={() => void openProof(payment.proof_asset_id!)} disabled={proofBusy !== null}>{proofBusy === payment.proof_asset_id ? "打开中…" : "查看凭证"}</button> : "未提供"}</span><span className="row-actions"><input className="review-note" value={notes[payment.id] ?? ""} onChange={(e) => setNotes({ ...notes, [payment.id]: e.target.value })} placeholder="驳回原因" /><button className="secondary-button small" onClick={() => void review(payment.id, "approved")} disabled={busy}>批准</button><button className="secondary-button small" onClick={() => void review(payment.id, "rejected")} disabled={busy}>驳回</button></span></div>)}</div> : <Empty title="暂无待审核付款" text="客户提交付款后，记录会出现在这里。" />}</section><section className="panel table-panel"><PanelTitle title="退款待审核" kicker={`${refunds.length} REFUNDS`} />{refunds.length ? <div className="data-table finance-table"><div className="table-head"><span>订单</span><span>金额</span><span>原因</span><span>申请时间</span><span>审核</span></div>{refunds.map((refund) => <div className="table-row" key={refund.id}><strong>{refund.order_id.slice(0, 8)}</strong><span>{money(refund.amount_minor)}</span><span>{refund.reason}</span><span>{new Date(refund.created_at).toLocaleString("zh-CN")}</span><span className="row-actions"><input className="review-note" value={notes[refund.id] ?? ""} onChange={(e) => setNotes({ ...notes, [refund.id]: e.target.value })} placeholder="驳回原因" /><button className="secondary-button small" onClick={() => void reviewRefundAction(refund.id, "approved")} disabled={busy}>批准</button><button className="secondary-button small" onClick={() => void reviewRefundAction(refund.id, "rejected")} disabled={busy}>驳回</button></span></div>)}</div> : <Empty title="暂无待审核退款" text="订单提交退款申请后会出现在这里。" />}</section><section className="panel table-panel"><PanelTitle title="财务对账" kicker={`${reconciliation.length} ORDERS`} /><div className="data-table finance-table"><div className="table-head"><span>订单</span><span>应收</span><span>已收</span><span>已退</span><span>状态</span></div>{reconciliation.map((row) => <div className="table-row" key={row.orderId}><strong>{row.orderNo}</strong><span>{money(row.dueMinor)}</span><span>{money(row.approvedPaymentMinor)}</span><span>{money(row.approvedRefundMinor)}</span><span className={`state-chip ${row.approvedPaymentMinor - row.approvedRefundMinor === row.dueMinor ? "good" : ""}`}>{statusText[row.paymentStatus] || row.paymentStatus}</span></div>)}</div></section></>;
}

function Schedules({ schedules, data, onRefresh }: { schedules: Schedule[]; data: DataState; onRefresh: () => Promise<void> }) { const [orderId, setOrderId] = useState(""); const [startAt, setStartAt] = useState(""); const [endAt, setEndAt] = useState(""); const [message, setMessage] = useState(""); const [busy, setBusy] = useState(false); const submit = async () => { setBusy(true); setMessage(""); try { await createSchedule(orderId, { scheduleType: "once", startAt: new Date(startAt).toISOString(), endAt: new Date(endAt).toISOString(), timezone: "Asia/Shanghai" }); setMessage("排期已创建，发布任务已进入队列"); setOrderId(""); setStartAt(""); setEndAt(""); await onRefresh(); } catch (e) { setMessage(e instanceof Error ? e.message : "创建排期失败"); } finally { setBusy(false); } }; const approvedOrders = data.orders.filter((o) => o.status === "approved"); return <><section className="action-panel panel"><div><div className="panel-kicker">PUBLISH SCHEDULING</div><h2>创建发布排期</h2><p>只有已审核通过的订单可以进入生产排期；创建后会生成发布任务。</p></div><div className="form-grid"><select value={orderId} onChange={(e) => setOrderId(e.target.value)}><option value="">选择已通过订单 *</option>{approvedOrders.map((o) => <option key={o.id} value={o.id}>{o.order_no} · {money(o.receivable_minor)}</option>)}</select><input type="datetime-local" value={startAt} onChange={(e) => setStartAt(e.target.value)} /><input type="datetime-local" value={endAt} onChange={(e) => setEndAt(e.target.value)} /><button className="primary-button" onClick={submit} disabled={busy || !orderId || !startAt || !endAt}>{busy ? "创建中…" : "创建排期"}</button></div>{message && <div className="form-message">{message}</div>}</section><section className="panel table-panel"><PanelTitle title="排期日历" kicker={`${schedules.length} SCHEDULES`} />{schedules.length ? <div className="schedule-list">{schedules.map((s) => <div className="schedule-row" key={s.id}><div className="date-box">{new Date(s.scheduled_at).toLocaleDateString("zh-CN", { month: "2-digit", day: "2-digit" })}</div><div><strong>订单 {s.order_id.slice(0, 8)}</strong><span>{new Date(s.scheduled_at).toLocaleString("zh-CN")}</span></div><span className="state-chip">{statusText[s.status] || s.status}</span></div>)}</div> : <Empty title="暂无排期" text="订单审核通过后，可以创建发布排期。" />}</section></>; }
function Records({ title, records, empty }: { title: string; records: Record<string, unknown>[]; empty: string }) { return <section className="panel table-panel"><PanelTitle title={title} kicker={`${records.length} RECORDS`} />{records.length ? <div className="record-list">{records.map((record, index) => <div className="record-row" key={String(record.id ?? index)}><div><strong>{String(record.file_name ?? record.order_id ?? record.id ?? "记录")}</strong><span>{String(record.media_type ?? record.status ?? "已入库")}</span></div><span className="state-chip">{statusText[String(record.status)] || String(record.status ?? "已就绪")}</span></div>)}</div> : <Empty title="暂无数据" text={empty} />}</section>; }
function OrderTable({ orders }: { orders: Order[] }) { return <div className="data-table"><div className="table-head"><span>订单号</span><span>状态</span><span>应收金额</span><span>更新时间</span></div>{orders.map((o) => <div className="table-row" key={o.id}><strong>{o.order_no}</strong><span className="state-chip">{statusText[o.status] || o.status}</span><span>{money(o.receivable_minor)}</span><span>{new Date(o.updated_at).toLocaleDateString("zh-CN")}</span></div>)}</div>; }
function ChannelTable({ channels }: { channels: Channel[] }) { return <div className="data-table"><div className="table-head"><span>频道</span><span>状态</span><span>发布</span><span>权限</span></div>{channels.map((c) => <div className="table-row" key={c.id}><strong>{c.title || c.username || c.telegram_chat_id}</strong><span className={`state-chip ${c.status === "active" ? "good" : ""}`}>{statusText[c.status] || c.status}</span><span>{c.can_post ? "可发布" : "无权限"}</span><span>{[c.can_post && "发布", c.can_pin && "置顶", c.can_delete && "删除"].filter(Boolean).join(" · ") || "待检查"}</span></div>)}</div>; }
function CustomerTable({ customers }: { customers: Customer[] }) { return <div className="data-table"><div className="table-head"><span>客户</span><span>联系方式</span><span>状态</span><span>累计消费</span></div>{customers.map((c) => <div className="table-row" key={c.id}><strong>{c.name}</strong><span>{c.contact || c.telegram_username || "—"}</span><span className="state-chip good">{statusText[c.status] || c.status}</span><span>{money(c.total_spend_minor)}</span></div>)}</div>; }
function Empty({ title, text, action, onClick }: { title: string; text: string; action?: string; onClick?: () => void }) { return <div className="empty-state"><div className="empty-icon"><Activity size={20} /></div><h3>{title}</h3><p>{text}</p>{action && <button className="secondary-button" onClick={onClick}>{action}<ChevronRight size={15} /></button>}</div>; }

export default App;
